INSERT INTO `study_units` (id, name, en, theme, intro, introZh, outro, outroZh) VALUES
('1', '第 1 单元 · 生活与日常', 'Unit 1 · Everyday Life', '围绕生活与日常主题，积累 200 个高频实用词。', 'Today we focus on everyday life. Read each sentence and notice how the words work in real situations.', '今天我们聚焦生活与日常。请朗读每个句子，体会单词在真实场景中的用法。', 'Small words build strong sentences. Try to retell the passage in your own words.', '小词堆出好句子。试着用自己的话复述这段短文。'),
('2', '第 2 单元 · 家庭与朋友', 'Unit 2 · Family & Friends', '围绕家庭与朋友主题，积累 200 个高频实用词。', 'Today we focus on family & friends. Read each sentence and notice how the words work in real situations.', '今天我们聚焦家庭与朋友。请朗读每个句子，体会单词在真实场景中的用法。', 'Small words build strong sentences. Try to retell the passage in your own words.', '小词堆出好句子。试着用自己的话复述这段短文。'),
