('5936', '297', '16', 'judgment', 'n.', '判断', 'Delay judgment until you have enough reliable facts.', '有足够可靠事实前暂缓判断。'),
('5937', '297', '17', 'assumption', 'n.', '假设', 'State your assumptions clearly at the beginning.', '开头清晰说明你的假设。'),
