('6526', '327', '6', 'march', 'v.', '行进', 'The students marched in neat lines during the school parade.', '学生在学校游行中整齐列队行进。'),
('6527', '327', '7', 'mark', 'n.', '标记，分数', 'She got full marks in the English spelling test.', '她英语拼写测验得满分。'),
('6528', '327', '8', 'marry', 'v.', '结婚', 'They decided to marry after knowing each other for five years.', '相识五年后他们决定结婚。'),
('6529', '327', '9', 'marvelous', 'adj.', '了不起的', 'The view from the top of the mountain is truly marvelous.', '山顶景色真正了不起。'),
('6530', '327', '10', 'mask', 'n.', '面具', 'The children wore colorful masks at the school festival.', '孩子们在学校节庆戴彩色面具。'),
('6531', '327', '11', 'master', 'n.', '大师，主人', 'He is a true master of traditional Chinese calligraphy.', '他是真正中国书法大师。'),
('6532', '327', '12', 'matter', 'n.', '事情，要紧', 'It does not matter if we arrive a few minutes late.', '我们晚几分钟到没关系。'),
('6533', '327', '13', 'mature', 'adj.', '成熟的', 'She has a mature and thoughtful way of solving problems.', '她解决问题成熟周全。'),
('6534', '327', '14', 'maximum', 'adj.', '最大的', 'The classroom can hold a maximum of forty students.', '教室最多容纳四十名学生。'),
('6535', '327', '15', 'maybe', 'adv.', '也许', 'Maybe we should wait for the rain to stop first.', '也许我们应先等雨停。'),
('6536', '327', '16', 'mayor', 'n.', '市长', 'The mayor opened the new community center yesterday.', '市长昨天启用新社区中心。'),
('6537', '327', '17', 'mean', 'v.', '意味着', 'A little daily practice can mean great progress over a year.', '每天一点练习一年后意味着巨大进步。'),
('6538', '327', '18', 'mechanic', 'n.', '机械师', 'The kind mechanic repaired my bicycle for free.', '好心机械师免费修好我的自行车。'),
('6539', '327', '19', 'memorial', 'n.', '纪念碑', 'A small memorial stands in the center of the village square.', '村广场中央立着小纪念碑。'),
('6540', '327', '20', 'mention', 'v.', '提到', 'Did she mention the time of the final exam anywhere?', '她有提到期末考试任何时间吗？'),
('6541', '328', '1', 'mercy', 'n.', '仁慈', 'The judge showed mercy to the young first-time offender.', '法官对年轻初犯者显示仁慈。'),
('6542', '328', '2', 'mere', 'adj.', '仅仅的', 'A mere smile from her made the whole day brighter.', '她一个微笑就让整天明亮。'),
('6543', '328', '3', 'merit', 'n.', '优点', 'This plan has the great merit of being simple and practical.', '这计划有简单实用巨大优点。'),
('6544', '328', '4', 'merry', 'adj.', '快乐的', 'We had a merry time at the small winter party.', '小型冬日聚会上我们玩得很快乐。'),
('6545', '328', '5', 'mess', 'n.', '混乱', 'Your desk is in a terrible mess; please tidy it up.', '你桌子乱糟糟请整理一下。'),
('6546', '328', '6', 'middle', 'n.', '中间', 'She sits in the middle of the front row in class.', '她坐教室前排中间。'),
('6547', '328', '7', 'midnight', 'n.', '午夜', 'The old clock struck twelve exactly at midnight.', '老钟午夜正好敲十二下。'),
('6548', '328', '8', 'mile', 'n.', '英里', 'The small village is only two miles from here.', '小村庄离这里只有两英里。'),
('6549', '328', '9', 'mill', 'n.', '磨坊，工厂', 'An old water mill stands beside the quiet river.', '老水磨坊立在安静河边。'),
('6550', '328', '10', 'million', 'num.', '百万', 'Over a million people visit the museum each year.', '每年超过一百万人参观博物馆。'),
('6551', '328', '11', 'mind', 'n.', '头脑，心思', 'Keep an open mind when you hear new ideas.', '听到新想法时保持开放头脑。'),
('6552', '328', '12', 'mine', 'pron.', '我的', 'That red bicycle near the door is mine.', '门边那辆红色自行车是我的。'),
('6553', '328', '13', 'minimum', 'adj.', '最小的', 'You need a minimum of eight hours of sleep each night.', '每晚至少需要八小时睡眠。'),
('6554', '328', '14', 'minister', 'n.', '部长，牧师', 'The local minister visited families in the small village.', '当地牧师探访小村庄家庭。'),
('6555', '328', '15', 'minor', 'adj.', '较小的', 'There was a minor problem with the computer this morning.', '今早电脑出了个小问题。'),
('6556', '328', '16', 'minority', 'n.', '少数', 'Only a small minority of students chose the advanced course.', '只有少数学生选高级课程。'),
('6557', '328', '17', 'miss', 'v.', '想念，错过', 'I really miss the quiet mornings in my hometown.', '我真的很想念家乡安静早晨。'),
('6558', '328', '18', 'model', 'n.', '模型，榜样', 'She is a good role model for younger students.', '她是低年级学生好榜样。'),
('6559', '328', '19', 'modest', 'adj.', '谦虚的', 'He stayed modest despite winning the top prize.', '获最高奖后他仍保持谦虚。'),
('6560', '328', '20', 'month', 'n.', '月份', 'The whole month passed by much faster than I expected.', '整月过得比预想快得多。'),
('6561', '329', '1', 'moral', 'adj.', '道德的', 'The story teaches a clear moral lesson about honesty.', '故事教关于诚实明确道德一课。'),
('6562', '329', '2', 'more', 'adj.', '更多的', 'I need a little more time to finish this difficult chapter.', '我需要多一点时间读完这难章。'),
('6563', '329', '3', 'morning', 'n.', '早晨', 'I enjoy a quiet cup of tea every early morning.', '我享受每个清晨安静一杯茶。'),
('6564', '329', '4', 'most', 'adj.', '最多的', 'Most students finished the exercise before the bell rang.', '多数学生铃响前完成练习。'),
('6565', '329', '5', 'motor', 'n.', '马达', 'The small electric motor runs almost without any noise.', '小电机几乎无噪音运转。'),
('6566', '329', '6', 'mouse', 'n.', '老鼠', 'A tiny mouse ran quickly across the old kitchen floor.', '小老鼠快速跑过旧厨房地板。'),
('6567', '329', '7', 'mouth', 'n.', '嘴', 'She covered her mouth politely when she yawned.', '打哈欠时她礼貌捂住嘴。'),
('6568', '329', '8', 'much', 'adj.', '许多', 'Thank you very much for your patient help today.', '非常感谢你今天耐心帮助。'),
('6569', '329', '9', 'mud', 'n.', '泥', 'The children came home with mud all over their shoes.', '孩子们回家鞋上满是泥。'),
('6570', '329', '10', 'multiply', 'v.', '乘，繁殖', 'Multiply the two numbers carefully before writing the answer.', '写答案前仔细把两数相乘。'),
