('6572', '329', '12', 'muscle', 'n.', '肌肉', 'Stretching helps relax tight muscles after long exercise.', '拉伸帮助放松长时间运动后紧绷肌肉。'),
('6573', '329', '13', 'mushroom', 'n.', '蘑菇', 'We picked fresh mushrooms in the woods after the rain.', '雨后我们在树林采鲜蘑菇。'),
('6574', '329', '14', 'musician', 'n.', '音乐家', 'The young musician practiced the violin for hours daily.', '年轻音乐家每天练小提琴数小时。'),
('6575', '329', '15', 'must', 'aux.', '必须', 'You must finish your homework before watching TV.', '看电视前你必须完成作业。'),
('6576', '329', '16', 'mystery', 'n.', '谜', 'The old locked room remains a local mystery to everyone.', '上锁老房间对每个人仍是当地谜团。'),
('6577', '329', '17', 'naked', 'adj.', '裸的', 'The child ran naked through the garden on the hot summer day.', '炎热夏日孩子赤身跑过花园。'),
('6578', '329', '18', 'narrow', 'adj.', '狭窄的', 'A narrow path leads quietly up to the old temple.', '狭窄小径静静通向古庙。'),
