('6580', '329', '20', 'national', 'adj.', '国家的', 'The national library holds a huge collection of rare books.', '国家图书馆藏大量善本。'),
('6581', '330', '1', 'native', 'adj.', '本地的，母语的', 'She is a native speaker of beautiful spoken English.', '她是优美英语口语母语者。'),
