('6583', '330', '3', 'necessary', 'adj.', '必要的', 'It is necessary to review new words regularly each week.', '每周定期复习新词是必要的。'),
('6584', '330', '4', 'need', 'v.', '需要', 'We need more time to carefully check every small detail.', '我们需要更多时间仔细检查每个小细节。'),
('6585', '330', '5', 'negative', 'adj.', '消极的', 'Try to replace negative thoughts with hopeful ones.', '试着用希望想法取代消极想法。'),
('6586', '330', '6', 'neglect', 'v.', '忽视', 'Do not neglect the small details in any important project.', '任何重要项目都不要忽视小细节。'),
('6587', '330', '7', 'neither', 'adv.', '也不', 'Neither answer is completely correct in my opinion.', '我认为两个答案都不完全正确。'),
('6588', '330', '8', 'nerve', 'n.', '神经，勇气', 'It took real nerve to speak in front of so many people.', '在这么多人面前讲话需要真勇气。'),
