('6590', '330', '10', 'never', 'adv.', '从不', 'He has never been late for an important meeting.', '他重要会议从不迟到。'),
('6591', '330', '11', 'new', 'adj.', '新的', 'Every new day brings another chance to learn something useful.', '每个新日子带来学习有用东西的机会。'),
('6592', '330', '12', 'newspaper', 'n.', '报纸', 'My grandfather reads the local newspaper every morning without fail.', '爷爷每天早上必读当地报纸。'),
