('6598', '330', '18', 'none', 'pron.', '没有一个', 'None of the students could answer that hard question.', '没有学生能回答那个难题。'),
('6599', '330', '19', 'noon', 'n.', '中午', 'The sun is strongest at noon on a clear summer day.', '晴天夏日中午阳光最强。'),
('6600', '330', '20', 'normal', 'adj.', '正常的', 'It is perfectly normal to feel tired after a long flight.', '长途飞行后感到累完全正常。'),
