('6611', '331', '11', 'occur', 'v.', '发生', 'Accidents like this rarely occur in our quiet neighborhood.', '这类事故在我们安静社区很少发生。'),
('6612', '331', '12', 'offend', 'v.', '冒犯', 'I hope my honest words did not offend anyone in the room.', '希望我坦诚话语没冒犯在座任何人。'),
