('6634', '332', '14', 'output', 'n.', '产量，输出', 'The new machine has doubled our daily output.', '新机器使我们日产量翻倍。'),
('6635', '332', '15', 'outside', 'prep.', '在…外面', 'The children were playing outside in the warm afternoon sun.', '孩子们在温暖下午阳光中户外玩耍。'),
