('6654', '333', '14', 'percent', 'n.', '百分之', 'Nearly sixty percent of the students chose the science course.', '近百分之六十学生选理科。'),
('6655', '333', '15', 'perfect', 'adj.', '完美的', 'Nobody is perfect, but we can all keep improving slowly.', '没人是完美的但我们都能慢慢进步。'),
