('6805', '341', '5', 'section', 'n.', '部分', 'The second section of the test is much more challenging.', '测试第二部分更具挑战性。'),
('6806', '341', '6', 'secure', 'adj.', '安全的', 'Make sure your personal information stays completely secure online.', '确保个人信息在网上完全安全。'),
('6807', '341', '7', 'see', 'v.', '看见', 'I was glad to see so many old friends at the school reunion.', '很高兴在校友聚会见到这么多老朋友。'),
('6808', '341', '8', 'seek', 'v.', '寻找', 'Many students seek advice from teachers before choosing a career path.', '许多学生选职业路前寻求老师建议。'),
('6809', '341', '9', 'seem', 'v.', '似乎', 'It seems that this difficult problem has a surprisingly simple solution.', '似乎这难题有出奇简单解法。'),
('6810', '341', '10', 'seize', 'v.', '抓住', 'She seized the good chance to study abroad for one full year.', '她抓住出国留学一整年好机会。'),
('6811', '341', '11', 'seldom', 'adv.', '很少', 'He seldom watches television because he prefers reading real books.', '他很少看电视因更喜欢读实体书。'),
('6812', '341', '12', 'select', 'v.', '选择', 'Please select three words from each list and write sentences with them.', '请从每表选三词并造句。'),
('6813', '341', '13', 'sell', 'v.', '卖', 'The small shop sells handmade gifts at very reasonable prices.', '小店以合理价格卖手工礼物。'),
('6814', '341', '14', 'send', 'v.', '发送', 'I will send you the complete notes after class this afternoon.', '下午下课后我会把完整笔记发你。'),
('6815', '341', '15', 'senior', 'adj.', '年长的', 'My senior classmates gave us a lot of useful advice about university life.', '高年级同学给我们很多大学生活建议。'),
('6816', '341', '16', 'sense', 'n.', '感觉', 'Her kind words gave us a real sense of warmth and belonging.', '她善意话给我们真实温暖归属感。'),
('6817', '341', '17', 'sensitive', 'adj.', '敏感的', 'He is very sensitive to criticism from people he respects greatly.', '他对尊敬之人批评非常敏感。'),
('6818', '341', '18', 'separate', 'adj.', '分开的', 'Keep the clean and dirty clothes in two separate bags.', '干净和脏衣服放两个分开袋子。'),
('6819', '341', '19', 'series', 'n.', '系列', 'The library has a popular new series of short mystery novels.', '图书馆有受欢迎新系列短悬疑小说。'),
('6820', '341', '20', 'serious', 'adj.', '严肃的', 'The teacher became serious when discussing classroom safety rules.', '讨论课堂安全规则时老师变得严肃。'),
('6821', '342', '1', 'seven', 'num.', '七', 'There are seven days in a complete week for study and review.', '完整一周有七天用于学习和复习。'),
('6822', '342', '2', 'several', 'adj.', '几个', 'Several old friends came to the small birthday celebration.', '几位老朋友来参加小型生日庆祝。'),
('6823', '342', '3', 'severe', 'adj.', '严重的', 'The patient suffered a severe illness but recovered slowly over months.', '病人患重病但数月内慢慢康复。'),
('6824', '342', '4', 'shadow', 'n.', '影子', 'A long dark shadow stretched across the quiet garden path.', '长长黑影延伸过安静花园小路。'),
('6825', '342', '5', 'shake', 'v.', '摇动', 'He shook his head slowly when he heard the surprising answer.', '听到惊人答案他缓缓摇头。'),
('6826', '342', '6', 'shall', 'aux.', '将', 'We shall begin the new reading plan at the start of next month.', '下月初我们将开始新阅读计划。'),
('6827', '342', '7', 'sharp', 'adj.', '锋利的，敏锐的', 'A sharp knife makes cutting vegetables much safer and faster.', '锋利刀让切菜更安全快捷。'),
('6828', '342', '8', 'sheep', 'n.', '羊', 'A small flock of white sheep grazed quietly on the green hill.', '小群白羊在青山安静吃草。'),
('6829', '342', '9', 'sheet', 'n.', '床单，一张', 'She changed the clean white sheets on the guest bed every week.', '她每周换客床干净白床单。'),
('6830', '342', '10', 'shell', 'n.', '壳', 'We collected colorful shells along the sandy beach at low tide.', '退潮时我们在沙滩捡彩色贝壳。'),
('6831', '342', '11', 'shine', 'v.', '发光', 'The warm morning sun shone brightly through the clean window.', '温暖晨光透过干净窗户明亮照耀。'),
('6832', '342', '12', 'shock', 'n.', '震惊', 'The sudden bad news came as a great shock to the whole family.', '突发坏消息让全家极为震惊。'),
('6833', '342', '13', 'shoot', 'v.', '射击，拍摄', 'The team plans to shoot a short film about school life.', '团队计划拍关于校园生活短片。'),
('6834', '342', '14', 'short', 'adj.', '短的', 'We took a short break after finishing the difficult first section.', '完成难第一部分后我们短暂休息。'),
('6835', '342', '15', 'should', 'aux.', '应该', 'You should review the new words before going to bed tonight.', '今晚睡前你应该复习新词。'),
('6836', '342', '16', 'shout', 'v.', '喊叫', 'There is no need to shout; I can hear you quite clearly.', '没必要喊我能听得很清楚。'),
('6837', '342', '17', 'shut', 'v.', '关闭', 'Please shut the door quietly so you do not wake the baby.', '请轻声关门以免吵醒婴儿。'),
('6838', '342', '18', 'sick', 'adj.', '生病的', 'She stayed home from school because she was sick with a cold.', '她因感冒生病没去上学。'),
('6839', '342', '19', 'side', 'n.', '边', 'A small wooden bench stands on the shady side of the garden.', '小木凳立在花园阴凉一侧。'),
('6840', '342', '20', 'sign', 'n.', '标志，签名', 'Please read the warning sign before entering the deep water area.', '进入深水区前请读警示标志。'),
('6841', '343', '1', 'silly', 'adj.', '愚蠢的', 'It was a silly mistake but we all learned from it together.', '那是愚蠢错误但我们都从中学习。'),
('6842', '343', '2', 'silver', 'adj.', '银色的', 'An old silver clock stands quietly on the wooden shelf.', '老银钟静静立在木架上。'),
('6843', '343', '3', 'similar', 'adj.', '相似的', 'The two answers are very similar but only one is correct.', '两答案很相似但只有一个正确。'),
('6844', '343', '4', 'since', 'prep.', '自从', 'She has been studying English since she was ten years old.', '她十岁起就一直学英语。'),
('6845', '343', '5', 'sing', 'v.', '唱歌', 'The children sing a cheerful song together at the start of each class.', '孩子们每节课前一起唱欢快歌。'),
('6846', '343', '6', 'single', 'adj.', '单一的', 'Not a single student was absent from the important morning assembly.', '重要晨会没有一个学生缺席。'),
('6847', '343', '7', 'sink', 'v.', '下沉', 'The small wooden boat began to sink slowly in the rough water.', '小木船在波涛中开始缓慢下沉。'),
('6848', '343', '8', 'sit', 'v.', '坐', 'Please sit down quietly and open your books to page twenty.', '请安静坐下把书翻到二十页。'),
('6849', '343', '9', 'site', 'n.', '地点', 'The old temple is an important historical site near our town.', '古庙是我镇附近重要历史遗址。'),
('6850', '343', '10', 'situation', 'n.', '情况', 'The difficult situation improved greatly after careful patient work.', '艰难情况在耐心工作后大大改善。'),
('6851', '343', '11', 'six', 'num.', '六', 'The study group meets twice a week for six whole weeks.', '学习小组每周两次共六整周。'),
('6852', '343', '12', 'slow', 'adj.', '慢的', 'A slow steady pace is better than rushing through difficult work.', '缓慢稳定步伐胜过匆忙完成难工作。'),
('6853', '343', '13', 'smart', 'adj.', '聪明的', 'Her smart solution to the problem impressed the whole class.', '她聪明解决方案让全班印象深刻。'),
('6854', '343', '14', 'smell', 'n.', '气味', 'The fresh smell of bread filled the whole warm kitchen.', '新面包香味充满整个温暖厨房。'),
('6855', '343', '15', 'smoke', 'n.', '烟', 'Thick black smoke rose slowly from the old chimney in the distance.', '远处老烟囱缓缓升起浓黑烟。'),
('6856', '343', '16', 'smooth', 'adj.', '光滑的', 'The new wooden desk has a surprisingly smooth surface.', '新木桌表面出奇光滑。'),
('6857', '343', '17', 'snake', 'n.', '蛇', 'A small green snake moved quietly through the tall wet grass.', '小绿蛇在高湿草中静静穿行。'),
('6858', '343', '18', 'so', 'adv.', '如此', 'The exam was so difficult that many students needed extra time.', '考试如此难以至于许多学生需额外时间。'),
('6859', '343', '19', 'sock', 'n.', '袜子', 'He could not find the matching sock in the messy drawer.', '他在乱抽屉找不到配对袜子。'),
('6860', '343', '20', 'soft', 'adj.', '柔软的', 'The soft music and warm light created a deeply relaxing evening atmosphere.', '柔音乐暖光营造深深放松夜晚氛围。'),
('6861', '344', '1', 'soldier', 'n.', '士兵', 'The brave soldier helped local people during the serious flood disaster.', '勇敢士兵在严重洪灾中帮助当地人。'),
('6862', '344', '2', 'some', 'adj.', '一些', 'Some students prefer quiet individual study to loud group discussion.', '一些学生更喜欢安静个人学习而非大声小组讨论。'),
('6863', '344', '3', 'someone', 'pron.', '某人', 'Someone has left a small blue umbrella near the library entrance.', '有人把蓝小伞落在图书馆入口附近。'),
('6864', '344', '4', 'something', 'pron.', '某事', 'There is something special about this old family recipe worth preserving.', '这个家传食谱有值得保存特别之处。'),
('6865', '344', '5', 'sometimes', 'adv.', '有时', 'Sometimes I prefer a quiet walk to a busy shopping trip with friends.', '有时我更喜欢安静散步而非繁忙购物。'),
('6866', '344', '6', 'sort', 'n.', '种类', 'What sort of background music do you prefer when you study at home?', '你在家学习时喜欢哪种背景音乐？'),
('6867', '344', '7', 'soul', 'n.', '灵魂', 'The moving film touched the deepest part of every viewer\'s soul.', '感人电影触动每位观众灵魂深处。'),
('6868', '344', '8', 'south', 'n.', '南方', 'Many migratory birds fly south to warmer lands before the cold winter arrives.', '寒冬前许多候鸟南飞暖地。'),
('6869', '344', '9', 'spare', 'adj.', '多余的', 'Could you spare a few minutes to look at my draft essay, please?', '能抽几分钟看我作文草稿吗？'),
('6870', '344', '10', 'speak', 'v.', '说话', 'She can speak three languages with surprising natural fluency and ease.', '她能惊人自然流利说三种语言。'),
('6871', '344', '11', 'special', 'adj.', '特别的', 'This old notebook has a very special place in my childhood memories.', '旧笔记本在我童年记忆中有特别位置。'),
('6872', '344', '12', 'specific', 'adj.', '具体的', 'The teacher gave us very specific advice on how to improve our writing.', '老师就如何改善写作给非常具体建议。'),
('6873', '344', '13', 'speech', 'n.', '演讲', 'Her short speech about kindness received long warm applause at the end.', '她关于善意简短演讲获长时间热烈掌声。'),
('6874', '344', '14', 'spell', 'v.', '拼写', 'I often misspell this word because its English spelling is quite unusual.', '我常拼错这词因其英文拼写很不寻常。'),
('6875', '344', '15', 'spite', 'n.', '怨恨', 'He said it out of spite, not because he truly meant any real harm.', '他说出于怨恨而非真有恶意。'),
('6876', '344', '16', 'split', 'v.', '分开', 'We split the long reading passage into three smaller easier sections.', '我们把长文章拆成三个更小易读部分。'),
('6877', '344', '17', 'spoil', 'v.', '破坏', 'A single careless answer spoiled his otherwise excellent test result.', '一个粗心答案破坏他原本优异成绩。'),
('6878', '344', '18', 'sponsor', 'n.', '赞助商', 'A local business agreed to be the main sponsor of the school sports day.', '当地企业同意做校运会主要赞助商。'),
('6879', '344', '19', 'spoon', 'n.', '勺子', 'She stirred the hot soup gently with a clean silver spoon.', '她用干净银勺轻搅热汤。'),
('6880', '344', '20', 'spot', 'n.', '地点，斑点', 'This quiet corner is the best spot in the library for deep reading.', '安静角落是图书馆深度阅读最佳地点。'),
('6881', '345', '1', 'spread', 'v.', '传播', 'Good news about the successful event spread quickly through the whole school.', '活动成功好消息迅速传遍全校。'),
('6882', '345', '2', 'spring', 'n.', '春天', 'Spring is the season when everything wakes up after the long cold winter.', '春天是漫长寒冬后万物苏醒季节。'),
('6883', '345', '3', 'stable', 'adj.', '稳定的', 'His condition remained stable throughout the long night after the operation.', '手术后的漫长夜晚他情况保持稳定。'),
('6884', '345', '4', 'staff', 'n.', '员工', 'The school library staff are always friendly and ready to help students.', '图书馆员工总是友好乐于帮助学生。'),
('6885', '345', '5', 'stand', 'v.', '站立', 'Please stand in a neat line and wait for your turn patiently.', '请整齐排队耐心等待轮到你。'),
('6886', '345', '6', 'standard', 'n.', '标准', 'The school has high standards for both academic work and daily behavior.', '学校对学业和日常行为都有高标准。'),
('6887', '345', '7', 'stare', 'v.', '凝视', 'Do not stare at people you do not know in a polite public place.', '公共场合不要盯着陌生人看。'),
('6888', '345', '8', 'start', 'v.', '开始', 'Let us start the new study plan with just twenty minutes a day.', '让我们从每天二十分钟开始新学习计划。'),
('6889', '345', '9', 'state', 'n.', '状态，陈述', 'The old building is in a surprisingly good state after many years.', '老楼多年后状态出奇好。'),
('6890', '345', '10', 'stay', 'v.', '停留', 'I stayed quietly in the library until the rain stopped late in the afternoon.', '我静静待图书馆直到下午晚些时候雨停。'),
('6891', '345', '11', 'steal', 'v.', '偷', 'Someone stole my bicycle from outside the library yesterday afternoon.', '昨天下午有人从图书馆外偷我自行车。'),
('6892', '345', '12', 'steel', 'n.', '钢', 'The new bridge is built from strong modern steel and concrete.', '新桥由坚固现代钢和混凝土建成。'),
('6893', '345', '13', 'stick', 'v.', '粘贴，坚持', 'Stick to your simple daily plan even when progress feels slow and invisible.', '即使进步缓慢隐形也坚持简单日常计划。'),
('6894', '345', '14', 'stock', 'n.', '库存', 'The shop is well stocked with fresh fruit and vegetables every morning.', '商店每天早上备足新鲜果蔬。'),
('6895', '345', '15', 'stop', 'v.', '停止', 'The heavy rain did not stop until late in the cold evening.', '大雨直到寒冷夜晚很晚才停。'),
('6896', '345', '16', 'straight', 'adj.', '直的', 'Walk straight along this quiet street and you will see the small library.', '沿安静街道直走你会看到小图书馆。'),
('6897', '345', '17', 'strange', 'adj.', '奇怪的', 'It feels strange to return to a place after so many busy years.', '多年忙碌后回到故地感觉奇怪。'),
('6898', '345', '18', 'strike', 'v.', '打击，罢工', 'A bright idea suddenly struck him while he was walking quietly in the park.', '公园静走时他突然想到绝妙主意。'),
('6899', '345', '19', 'string', 'n.', '绳子', 'She tied the small package securely with a piece of thin brown string.', '她用细棕绳把小包捆牢。'),
('6900', '345', '20', 'strip', 'n.', '条', 'He tore a long thin strip of paper from the edge of the old notebook.', '他从旧笔记本边缘撕下细长纸条。'),
('6901', '346', '1', 'struggle', 'v.', '挣扎，努力', 'Many students struggle with English speaking but improve through daily practice.', '许多学生口语挣扎但每日练习会进步。'),
('6902', '346', '2', 'stuff', 'n.', '东西', 'I left all my study stuff on the desk before going out for lunch.', '午饭外出前我把学习用品都放桌上。'),
('6903', '346', '3', 'stupid', 'adj.', '愚蠢的', 'It was a stupid mistake but it taught us all a useful lesson.', '那是愚蠢错误但教我们有用一课。'),
('6904', '346', '4', 'submit', 'v.', '提交', 'Please submit your final essay to the teacher before Friday afternoon.', '周五下午前请向老师提交期末论文。'),
('6905', '346', '5', 'substitute', 'n.', '替代品', 'Honey can be a healthy natural substitute for white sugar in tea.', '蜂蜜可健康天然替代茶中白糖。'),
('6906', '346', '6', 'successful', 'adj.', '成功的', 'The school play was a surprisingly successful event for all the young actors.', '校戏剧对所有年轻演员是出奇成功活动。'),
('6907', '346', '7', 'such', 'adj.', '这样的', 'I have never seen such a beautiful old library in a small quiet town.', '我从未见过小镇里如此美丽古老图书馆。'),
('6908', '346', '8', 'sudden', 'adj.', '突然的', 'A sudden loud noise outside made everyone look up from their books.', '外面突然巨响让所有人从书中抬头。'),
('6909', '346', '9', 'suffer', 'v.', '遭受', 'The small town suffered greatly from the unexpected long drought last year.', '小镇去年遭受意外长期干旱严重损失。'),
('6910', '346', '10', 'sufficient', 'adj.', '充足的', 'Make sure you get sufficient sleep before a long difficult exam day.', '漫长难考试日前确保充足睡眠。'),
('6911', '346', '11', 'suit', 'v.', '适合', 'This quiet study method may not suit every single student in the class.', '安静学习法可能不适合班里每个学生。'),
('6912', '346', '12', 'sum', 'n.', '总数', 'The total sum of all the small daily efforts is truly impressive.', '所有每日小努力总和真正令人印象深刻。'),
('6913', '346', '13', 'summer', 'n.', '夏天', 'Long warm summer evenings are perfect for reading in the quiet garden.', '温暖长夏夜适合在安静花园阅读。'),
('6914', '346', '14', 'supper', 'n.', '晚餐', 'We had a simple quiet supper of rice and vegetables at home last night.', '昨晚我们在家吃米饭蔬菜简单安静晚餐。'),
('6915', '346', '15', 'suppose', 'v.', '假设', 'Suppose you had one free month; how would you spend it learning?', '假设你有一个月空闲你会如何用来学习？'),
('6916', '346', '16', 'sure', 'adj.', '确信的', 'I am quite sure that careful review helps long-term vocabulary memory.', '我很确信仔细复习有助长期词汇记忆。'),
('6917', '346', '17', 'surface', 'n.', '表面', 'A thin layer of dust covered the smooth surface of the old desk.', '薄尘覆盖老桌光滑表面。'),
('6918', '346', '18', 'surprise', 'n.', '惊喜', 'Her beautiful handmade card was a lovely surprise on my birthday morning.', '她手工贺卡是我生日早晨可爱惊喜。'),
('6919', '346', '19', 'surround', 'v.', '围绕', 'Tall green trees surround the small peaceful village on every side.', '高大绿树从各面环绕安静小村。'),
('6920', '346', '20', 'suspect', 'v.', '怀疑', 'Police suspect that the old letter may reveal an important hidden clue.', '警方怀疑旧信可能揭示重要隐藏线索。'),
('6921', '347', '1', 'sustain', 'v.', '维持', 'It is hard to sustain such intense study effort for many long months.', '长期维持如此高强度学习努力很难。'),
('6922', '347', '2', 'swallow', 'v.', '吞咽', 'He swallowed the bitter medicine quickly with a large glass of water.', '他一大杯水快速吞下苦药。'),
('6923', '347', '3', 'swamp', 'n.', '沼泽', 'The wet swamp is home to many unusual birds and small amphibians.', '湿沼泽是许多不寻常鸟类和小两栖动物家园。'),
('6924', '347', '4', 'swear', 'v.', '发誓', 'She swore to keep the precious old family secret safe forever.', '她发誓永远保守珍贵家族秘密。'),
('6925', '347', '5', 'sweat', 'n.', '汗', 'After the long run, his face was covered in honest sweat and happiness.', '长跑后他脸上满是真诚汗水与快乐。'),
('6926', '347', '6', 'swing', 'v.', '摇摆', 'The old wooden gate swings gently in the cool evening breeze.', '老木门在凉爽晚风中轻轻摇摆。'),
('6927', '347', '7', 'switch', 'v.', '切换', 'Please switch off your mobile phone during the important examination.', '重要考试期间请关掉手机。'),
('6928', '347', '8', 'system', 'n.', '系统', 'The school introduced a new simple system for organizing library books.', '学校引入新简单系统整理图书馆书籍。'),
('6929', '347', '9', 'table', 'n.', '桌子', 'We sat around a large wooden table and shared a quiet family meal.', '我们围大木桌共享安静家庭餐。'),
('6930', '347', '10', 'tackle', 'v.', '处理', 'Let us tackle the most difficult reading passage first while we are fresh.', '让我们趁头脑清醒先处理最难阅读文章。'),
('6931', '347', '11', 'tag', 'n.', '标签', 'Each new word in the book has a small useful memory tag beside it.', '书中每个新词旁有小有用记忆标签。'),
('6932', '347', '12', 'take', 'v.', '拿，花费', 'It takes about twenty minutes to walk to the nearest public library.', '走到最近公共图书馆约需二十分钟。'),
('6933', '347', '13', 'talent', 'n.', '天赋', 'She has a real natural talent for learning foreign languages quickly.', '她有快速学外语真正天赋。'),
('6934', '347', '14', 'talk', 'v.', '谈话', 'We talked quietly for hours about books and old happy memories.', '我们安静聊数小时关于书与快乐回忆。'),
('6935', '347', '15', 'tall', 'adj.', '高的', 'A tall old tree stands proudly in the center of the quiet village square.', '高老树傲然立在安静村广场中央。'),
('6936', '347', '16', 'tame', 'adj.', '温顺的', 'The tame little bird would eat gently from the child\'s open hand.', '温顺小鸟会从孩子掌心轻啄食。'),
('6937', '347', '17', 'tap', 'v.', '轻拍', 'She tapped him gently on the shoulder to get his quiet attention.', '她轻拍他肩膀获取安静注意。'),
('6938', '347', '18', 'tear', 'v.', '撕裂', 'Be careful not to tear the thin old pages of this precious book.', '小心别撕破这本珍贵书薄老页。'),
('6939', '347', '19', 'teenager', 'n.', '青少年', 'Teenagers often need patient understanding rather than quick strict judgment.', '青少年常需耐心理解而非快速严格评判。'),
('6940', '347', '20', 'telephone', 'n.', '电话', 'The old telephone on the desk still rings clearly every morning.', '桌上老电话每天早上仍响得清晰。'),
('6941', '348', '1', 'tell', 'v.', '告诉', 'Could you tell me the exact time of the next train to the city?', '你能告诉我下一班进城火车确切时间吗？'),
('6942', '348', '2', 'ten', 'num.', '十', 'We review all new words once every ten days in this new study plan.', '新计划我们每十天复习一次所有新词。'),
('6943', '348', '3', 'tend', 'v.', '倾向于', 'I tend to remember words much better when I use them in real sentences.', '在真实句子中使用时我往往记得更好。'),
('6944', '348', '4', 'tender', 'adj.', '温柔的', 'She gave the frightened child a gentle and tender smile of comfort.', '她给受惊孩子温柔安慰微笑。'),
('6945', '348', '5', 'tennis', 'n.', '网球', 'They play a friendly game of tennis every Saturday afternoon in the park.', '每周六下午他们在公园打友好网球。'),
('6946', '348', '6', 'tense', 'adj.', '紧张的', 'The atmosphere in the room became tense during the difficult discussion.', '艰难讨论中房间气氛变紧张。'),
('6947', '348', '7', 'term', 'n.', '学期，术语', 'The new school term begins with a simple but useful study plan.', '新学期以简单实用学习计划开始。'),
('6948', '348', '8', 'terrible', 'adj.', '可怕的', 'The weather was terrible yesterday but today is bright and clear.', '昨天天气糟糕但今天晴朗。'),
('6949', '348', '9', 'territory', 'n.', '领土', 'The small protected territory is home to many rare wild animals.', '小保护区是许多稀有野生动物家园。'),
('6950', '348', '10', 'textbook', 'n.', '教科书', 'This old textbook has been a faithful companion through many years of study.', '旧教科书是多年学习忠实伙伴。'),
('6951', '348', '11', 'thank', 'v.', '感谢', 'I want to thank each of you for your patient help this busy month.', '我想感谢你们每个人这个忙碌月耐心帮助。'),
('6952', '348', '12', 'their', 'pron.', '他们的', 'The students brought their own favorite books to the quiet reading corner.', '学生把自己最爱书带到安静阅读角。'),
('6953', '348', '13', 'then', 'adv.', '然后', 'Finish your homework first and then you can enjoy a short relaxing break.', '先完成作业然后可享受短暂放松休息。'),
('6954', '348', '14', 'there', 'adv.', '那里', 'There is a small peaceful bookstore at the end of the quiet old street.', '安静老街尽头有小小宁静书店。'),
('6955', '348', '15', 'therefore', 'adv.', '因此', 'He worked steadily every day and therefore achieved excellent final results.', '他每天稳步努力因此取得优异期末成绩。'),
('6956', '348', '16', 'these', 'pron.', '这些', 'These useful expressions are very common in everyday spoken English.', '这些实用表达在日常英语口语中很常见。'),
('6957', '348', '17', 'they', 'pron.', '他们', 'They have been close friends since their early university days together.', '他们大学早期起就是密友。'),
('6958', '348', '18', 'thing', 'n.', '东西，事情', 'The most important thing is to keep going even on slow difficult days.', '最重要是即使缓慢艰难日子也继续前进。'),
('6959', '348', '19', 'think', 'v.', '思考', 'Take a moment to think carefully before you answer such a hard question.', '回答难题前花点时间仔细思考。'),
('6960', '348', '20', 'third', 'num.', '第三', 'She finished third in the school English reading competition last month.', '上月她在校英语阅读比赛获第三名。'),
('6961', '349', '1', 'thirst', 'n.', '口渴', 'A long walk in the hot sun naturally increases your thirst for cool water.', '烈日下长走自然增加对凉水口渴。'),
('6962', '349', '2', 'thorn', 'n.', '刺', 'A sharp thorn on the old rose bush pricked his finger gently.', '老玫瑰丛尖刺轻扎他手指。'),
('6963', '349', '3', 'though', 'conj.', '尽管', 'Though the task was difficult, they completed it with patient careful work.', '尽管任务困难他们耐心工作完成。'),
('6964', '349', '4', 'thread', 'n.', '线', 'She used a thin needle and strong thread to repair the small hole in her coat.', '她用细针坚线补外套小洞。'),
('6965', '349', '5', 'threat', 'n.', '威胁', 'Pollution is a serious continuing threat to the small mountain ecosystem.', '污染是对小山地生态严重持续威胁。'),
('6966', '349', '6', 'thrive', 'v.', '茁壮成长', 'Young plants thrive beautifully in warm sunny spring weather.', '幼苗在温暖阳光春日茁壮成长。'),
('6967', '349', '7', 'tie', 'n.', '领带，联系', 'He wore a blue silk tie to the formal school ceremony.', '正式校服仪式他系蓝色丝领带。'),
('6968', '349', '8', 'tiger', 'n.', '老虎', 'A beautiful tiger was quietly watching from behind the tall green grass.', '美丽老虎在高绿草后静静观察。'),
('6969', '349', '9', 'tile', 'n.', '瓷砖', 'The kitchen floor is covered in small clean white square tiles.', '厨房地面铺满干净白色小方瓷砖。'),
('6970', '349', '10', 'till', 'prep.', '直到', 'We studied quietly in the library till the sun went down outside.', '我们在图书馆静学到外面太阳落山。'),
('6971', '349', '11', 'tip', 'n.', '提示，尖端', 'The teacher gave us a very useful tip for remembering difficult new words.', '老师给我们记难新词非常有用提示。'),
('6972', '349', '12', 'tire', 'v.', '使疲倦', 'The long difficult journey tired everyone but the beautiful view was worth it.', '漫长艰难旅程让所有人疲惫但美景值得。'),
('6973', '349', '13', 'tissue', 'n.', '纸巾', 'She took a clean soft tissue from her bag to wipe her hands.', '她从包里拿干净柔纸巾擦手。'),
('6974', '349', '14', 'title', 'n.', '标题', 'Write a clear short title at the top of your new essay.', '在新作文顶部写清晰简短标题。'),
('6975', '349', '15', 'tobacco', 'n.', '烟草', 'The small shop stopped selling tobacco products to young people years ago.', '小店数年前停止向年轻人售烟草产品。'),
('6976', '349', '16', 'today', 'n.', '今天', 'Today is a good day to start a small but lasting new learning habit.', '今天是开始小而持久学习好习惯好日子。'),
('6977', '349', '17', 'toilet', 'n.', '厕所', 'Where is the nearest public toilet near this busy old train station?', '繁忙老火车站附近最近的公共厕所在哪儿？'),
('6978', '349', '18', 'tomato', 'n.', '西红柿', 'A fresh red tomato adds natural color and flavor to the simple salad.', '鲜红西红柿给简单沙拉添天然色味。'),
('6979', '349', '19', 'tomorrow', 'n.', '明天', 'I will bring my completed essay to class tomorrow morning without fail.', '明天早上我一定带完成作文来上课。'),
('6980', '349', '20', 'tongue', 'n.', '舌头', 'The spicy soup burned the tip of his tongue slightly but tasted wonderful.', '辣汤微烫舌尖但味道很棒。'),
('6981', '350', '1', 'tonight', 'adv.', '今晚', 'I plan to finish reading this short novel before I go to sleep tonight.', '今晚睡前我打算读完这本短小说。'),
('6982', '350', '2', 'too', 'adv.', '也，太', 'The soup is a little too hot for me to drink right now this minute.', '汤有点太烫我现在没法喝。'),
('6983', '350', '3', 'tool', 'n.', '工具', 'A good dictionary is an essential tool for every serious language learner.', '好词典是每个认真语言学习者必备工具。'),
('6984', '350', '4', 'top', 'n.', '顶部', 'She finished at the top of her class in the final English examination.', '期末英语考试她位列班级第一。'),
('6985', '350', '5', 'torch', 'n.', '手电筒', 'We used a small torch to find our way along the dark narrow path.', '我们用手电筒在黑暗小径找路。'),
('6986', '350', '6', 'touch', 'v.', '触摸', 'Please do not touch the ancient paintings in the quiet museum hall.', '安静博物馆厅请勿触摸古画。'),
('6987', '350', '7', 'toward', 'prep.', '朝向', 'He walked slowly toward the small bookshop at the end of the street.', '他缓慢朝街尾小书店走去。'),
('6988', '350', '8', 'tower', 'n.', '塔', 'An old stone tower stands quietly on the top of the green hill.', '古石塔静静立在青山顶。'),
('6989', '350', '9', 'town', 'n.', '城镇', 'Our small quiet town has a lovely bookstore and a friendly local market.', '安静小镇有可爱书店友好当地市场。'),
('6990', '350', '10', 'toy', 'n.', '玩具', 'The child carefully put all his wooden toys back into the clean box.', '孩子仔细把木玩具放回干净盒子。'),
('6991', '350', '11', 'trap', 'n.', '陷阱', 'The clever mouse avoided the small trap and ran quickly back into its hole.', '聪明老鼠避开小陷阱快速跑回洞。'),
('6992', '350', '12', 'trial', 'n.', '试验，审判', 'The new teaching method was tried as a small trial in two classes.', '新方法在两个班作为小试验试行。'),
('6993', '350', '13', 'tribe', 'n.', '部落', 'The book describes the quiet daily life of a small mountain tribe.', '书描述小山部落安静日常生活。'),
('6994', '350', '14', 'trick', 'n.', '诀窍，戏法', 'There is a simple memory trick that makes these new words much easier.', '有简单记忆诀窍让新词更容易。'),
('6995', '350', '15', 'trouble', 'n.', '麻烦', 'If you have any trouble with the new words, please ask me anytime.', '新词有麻烦请随时问我。'),
('6996', '350', '16', 'truck', 'n.', '卡车', 'A large red truck delivered fresh vegetables to the small market early today.', '大红卡车今早给小市场送新鲜蔬菜。'),
('6997', '350', '17', 'true', 'adj.', '真的', 'A true friend always tells you the honest truth even when it is hard.', '真正朋友即使困难也告诉你诚实真相。'),
('6998', '350', '18', 'try', 'v.', '尝试', 'Do not be afraid to try a new learning method that might suit you better.', '不要害怕尝试可能更适合你的新学习法。'),
('6999', '350', '19', 'tube', 'n.', '管子', 'A thin clear plastic tube carried the water quietly down to the garden.', '透明细塑料管安静把水引到花园。'),
('7000', '350', '20', 'tuck', 'v.', '塞进', 'She tucked the warm blanket carefully around the sleeping child.', '她仔细把暖毯掖在睡着孩子周围。'),
('7001', '351', '1', 'tunnel', 'n.', '隧道', 'The long dark mountain tunnel was built more than fifty years ago.', '漫长黑暗山隧道建于五十多年前。'),
('7002', '351', '2', 'turkey', 'n.', '火鸡', 'We had a simple roast turkey dinner with close family last autumn.', '去年秋天我们与亲近家人吃简单烤火鸡晚餐。'),
('7003', '351', '3', 'turn', 'v.', '转动', 'Please turn the page slowly and read the next short passage carefully.', '请缓慢翻页仔细读下一篇短文。'),
('7004', '351', '4', 'twelve', 'num.', '十二', 'The old clock struck twelve slowly in the quiet midnight air.', '老钟在安静午夜缓缓敲十二下。'),
('7005', '351', '5', 'twice', 'adv.', '两次', 'I review all my new vocabulary twice a week to keep it fresh in memory.', '我每周复习新词两次保持记忆新鲜。'),
('7006', '351', '6', 'twist', 'v.', '扭转', 'She twisted the wet cloth carefully with both hands over the small sink.', '她在水槽上双手小心拧干湿布。'),
('7007', '351', '7', 'two', 'num.', '二', 'There are only two students in the library reading room this quiet afternoon.', '安静下午图书馆阅览室只有两名学生。'),
('7008', '351', '8', 'type', 'n.', '类型', 'What type of English reading material do you enjoy most in your free time?', '空闲时你最喜欢哪类英语阅读材料？'),
('7009', '351', '9', 'ugly', 'adj.', '丑的', 'The old building is not beautiful but it has a certain quiet ugly charm.', '老建筑不美但有某种安静丑陋魅力。'),
('7010', '351', '10', 'umbrella', 'n.', '雨伞', 'Remember to take an umbrella because the forecast says rain later today.', '记得带伞因预报说今天晚些时候有雨。'),
('7011', '351', '11', 'unable', 'adj.', '不能的', 'He was unable to attend the meeting because of a sudden illness.', '他因突发疾病无法参加会议。'),
('7012', '351', '12', 'under', 'prep.', '在…下面', 'A small cat slept quietly under the warm wooden table all afternoon.', '小猫一下午在温暖木桌下安静睡觉。'),
('7013', '351', '13', 'underscore', 'v.', '强调', 'The teacher underscored the importance of careful daily review in class.', '老师在课堂强调仔细每日复习重要性。'),
('7014', '351', '14', 'undertake', 'v.', '承担', 'She agreed to undertake the difficult task with quiet confidence and patience.', '她带着安静信心耐心同意承担难任务。'),
('7015', '351', '15', 'unemployed', 'adj.', '失业的', 'The number of unemployed young people has fallen slightly this year.', '今年失业青年数量略有下降。'),
('7016', '351', '16', 'unfair', 'adj.', '不公平的', 'It is unfair to blame one person for a problem the whole group created.', '把全组造成问题怪一人不公平。'),
('7017', '351', '17', 'unfold', 'v.', '展开', 'The beautiful story slowly unfolds over ten short moving chapters.', '美丽故事在十短感人章节中慢慢展开。'),
('7018', '351', '18', 'unhappy', 'adj.', '不快乐的', 'She felt unhappy about the result but learned a valuable lesson from it.', '她对结果不开心但学到宝贵一课。'),
('7019', '351', '19', 'unit', 'n.', '单元', 'This new study plan is divided into twenty clear ten-day units.', '新学习计划分二十个清晰十天单元。'),
('7020', '351', '20', 'unless', 'conj.', '除非', 'You will not improve unless you practice speaking English every single day.', '除非每天练说英语否则你不会进步。'),
('7021', '352', '1', 'unlike', 'prep.', '不像', 'Unlike his quiet brother, he loves loud lively music and big parties.', '不像安静哥哥他喜欢响亮活泼音乐和大聚会。'),
('7022', '352', '2', 'until', 'prep.', '直到', 'We kept studying quietly in the library until it closed at ten.', '我们在图书馆静学到十点关门。'),
('7023', '352', '3', 'up', 'adv.', '向上', 'Please look up the new word in your dictionary before asking the teacher.', '问老师前请在词典查新词。'),
('7024', '352', '4', 'upon', 'prep.', '在…之上', 'Upon hearing the good news, the whole family smiled with great joy.', '听到好消息全家开心微笑。'),
('7025', '352', '5', 'upper', 'adj.', '上面的', 'She placed the heavy books on the upper shelf of the tall bookcase.', '她把重书放高书架上层。'),
('7026', '352', '6', 'urge', 'v.', '敦促', 'The doctor urged him to rest more and sleep better every night.', '医生敦促他每晚多休息睡好。'),
('7027', '352', '7', 'urgent', 'adj.', '紧急的', 'There is an urgent need for more clean water in the drought area.', '干旱地区急需更多净水。'),
('7028', '352', '8', 'use', 'v.', '使用', 'Use the new words in your own sentences to remember them much better.', '用新词自己造句以更好记住。'),
('7029', '352', '9', 'useful', 'adj.', '有用的', 'This simple study method has proved extremely useful over the past two months.', '过去两月这简单学习法证明极其有用。'),
('7030', '352', '10', 'usual', 'adj.', '通常的', 'She arrived at the library a little earlier than usual on that quiet morning.', '安静早晨她比平时早点到图书馆。'),
('7031', '352', '11', 'usually', 'adv.', '通常', 'I usually review new words for twenty minutes before going to bed each night.', '我通常每晚睡前复习新词二十分钟。'),
('7032', '352', '12', 'vacant', 'adj.', '空的', 'There are still a few vacant seats in the back row of the reading room.', '阅览室后排还有几个空座。'),
('7033', '352', '13', 'vague', 'adj.', '模糊的', 'His answer was rather vague and did not really solve our small problem.', '他回答相当模糊并未真正解决小问题。'),
('7034', '352', '14', 'valuable', 'adj.', '贵重的', 'Her patient advice has been extremely valuable to my new study plan.', '她耐心建议对我新学习计划极有价值。'),
('7035', '352', '15', 'variety', 'n.', '多样性', 'A rich variety of reading materials keeps daily language learning fresh and interesting.', '丰富多样阅读材料让日常语言学习新鲜有趣。'),
('7036', '352', '16', 'various', 'adj.', '各种各样的', 'The library offers various useful courses for students of all ages and levels.', '图书馆为各年龄水平学生提供各种有用课程。'),
('7037', '352', '17', 'vast', 'adj.', '广阔的', 'A vast field of golden wheat stretched out under the bright summer sky.', '广阔金色麦田在明亮夏日天空下延伸。'),
('7038', '352', '18', 'vehicle', 'n.', '车辆', 'This quiet electric vehicle produces no harmful smoke at all in the city.', '安静电动车在城市不产生有害烟雾。'),
('7039', '352', '19', 'venture', 'n.', '冒险', 'Starting a small business can be a risky but deeply rewarding venture.', '创业可能是冒险但极有回报事业。'),
('7040', '352', '20', 'verb', 'n.', '动词', 'English verbs change their form when we talk about the past clearly.', '谈论过去时英语动词会清楚改变形式。'),
('7041', '353', '1', 'verify', 'v.', '核实', 'Please verify the exact time of the meeting before you leave home today.', '离家前请核实会议确切时间。'),
('7042', '353', '2', 'version', 'n.', '版本', 'The new version of this useful app is much easier for beginners to use.', '应用新版本对初学者更易使用。'),
('7043', '353', '3', 'very', 'adv.', '非常', 'I am very grateful for all the patient help you gave me this month.', '我非常感激你本月给我所有耐心帮助。'),
('7044', '353', '4', 'vessel', 'n.', '船，容器', 'A small wooden vessel carried fresh fish into the busy morning market.', '小木船把鲜鱼运进繁忙早市。'),
('7045', '353', '5', 'veteran', 'adj.', '经验丰富的', 'The veteran teacher has guided hundreds of young students over the years.', '经验丰富老师多年指导数百年轻学生。'),
('7046', '353', '6', 'victim', 'n.', '受害者', 'The kind neighbors helped the flood victims rebuild their small homes.', '好心邻居帮洪灾受害者重建小家。'),
('7047', '353', '7', 'video', 'n.', '视频', 'A short English video with clear subtitles can greatly improve your listening.', '清晰字幕短英语视频能大幅提高听力。'),
('7048', '353', '8', 'village', 'n.', '村庄', 'The small mountain village has changed greatly over the past twenty peaceful years.', '山村过去二十年和平岁月变化很大。'),
('7049', '353', '9', 'violence', 'n.', '暴力', 'The story strongly condemns all forms of cruelty and needless violence.', '故事强烈谴责一切残忍与不必要暴力。'),
('7050', '353', '10', 'violent', 'adj.', '暴力的', 'A violent storm destroyed several old houses in the coastal town last night.', '昨夜暴风摧毁海滨小镇几座老房。'),
('7051', '353', '11', 'virtue', 'n.', '美德', 'Patience is a quiet virtue that grows slowly through difficult daily moments.', '耐心是在艰难日常中慢慢成长安静美德。'),
('7052', '353', '12', 'vision', 'n.', '视力，愿景', 'She has a clear vision of the kind of person she wants to become slowly.', '她清楚想象自己想慢慢成为什么样的人。'),
('7053', '353', '13', 'visual', 'adj.', '视觉的', 'Visual aids such as simple pictures can make new vocabulary much easier to learn.', '图片等视觉辅助让新词更易学。'),
('7054', '353', '14', 'vital', 'adj.', '至关重要的', 'Enough sleep is vital for both good physical health and clear daily thinking.', '充足睡眠对身体健康和清晰日常思维至关重要。'),
('7055', '353', '15', 'volleyball', 'n.', '排球', 'They play a friendly game of volleyball on the sandy beach every summer afternoon.', '每个夏日下午他们在沙滩打友好排球。'),
('7056', '353', '16', 'volume', 'n.', '音量，量', 'Please turn down the volume of the music while I am studying quietly.', '我安静学习时请调低音乐音量。'),
('7057', '353', '17', 'voyage', 'n.', '航行', 'The long sea voyage across the ocean took almost three difficult months.', '跨洋漫长海上航行花近三艰难月份。'),
('7058', '353', '18', 'wage', 'n.', '工资', 'He works hard every day to earn a fair wage for his growing family.', '他每天努力工作为成长家庭挣公平工资。'),
('7059', '353', '19', 'walk', 'v.', '走', 'We take a slow walk around the small park after a busy long day.', '忙碌长日后我们绕小公园慢走。'),
('7060', '353', '20', 'wallet', 'n.', '钱包', 'He lost his wallet somewhere between the busy market and the station.', '他在繁忙市场和车站间丢了钱包。'),
('7061', '354', '1', 'wander', 'v.', '漫步', 'We love to wander slowly through the quiet old streets on a sunny afternoon.', '阳光下午我们喜欢在安静老街漫步。'),
('7062', '354', '2', 'want', 'v.', '想要', 'I want to improve my English speaking through patient daily low-pressure practice.', '我想通过耐心每日低压力练习提高英语口语。'),
('7063', '354', '3', 'war', 'n.', '战争', 'The old book describes the terrible effects of war on ordinary families.', '老书描述战争对普通家庭可怕影响。'),
('7064', '354', '4', 'warn', 'v.', '警告', 'The teacher warned us about the danger of careless mistakes in the final test.', '老师警告我们期末测试中粗心错误危险。'),
('7065', '354', '5', 'watch', 'v.', '观看', 'We watched the sun go down slowly behind the quiet western hills.', '我们观看太阳在安静西山坡后缓缓落下。'),
('7066', '354', '6', 'water', 'n.', '水', 'Clean fresh water is essential for every living thing on our planet earth.', '洁净淡水对地球每个生物必不可少。'),
('7067', '354', '7', 'way', 'n.', '方法，路', 'Finding your own effective learning way takes honest patient experiments.', '找到自己有效学习法需诚实耐心试验。'),
('7068', '354', '8', 'weak', 'adj.', '虚弱的', 'He felt weak after the long illness but grew stronger with patient care.', '久病后他虚弱但耐心照料下渐强。'),
('7069', '354', '9', 'weapon', 'n.', '武器', 'The museum displays ancient weapons used in battles long ago.', '博物馆展示很久前战斗用古武器。'),
