('7073', '354', '13', 'wet', 'adj.', '湿的', 'The grass is still wet after the heavy rain early this cold morning.', '清晨大雨后草仍湿。'),
('7074', '354', '14', 'what', 'pron.', '什么', 'Please tell me what you learned from this difficult but useful passage.', '请告诉我你从这篇难但有用文章学到什么。'),
