('7076', '354', '16', 'when', 'conj.', '当…时', 'I feel most focused when the house is completely quiet early in the morning.', '清晨房子完全安静时我最专注。'),
('7077', '354', '17', 'whenever', 'conj.', '无论何时', 'You can ask me questions whenever you have trouble with new words.', '新词有困难时你随时可问我。'),
('7078', '354', '18', 'where', 'adv.', '哪里', 'This is the quiet little bookshop where I found my favorite old novel.', '这是我发现最爱老小说安静小书店。'),
('7079', '354', '19', 'whether', 'conj.', '是否', 'I am not sure whether this difficult method will really suit you well.', '我不确定这难方法是否真适合你。'),
('7080', '354', '20', 'which', 'pron.', '哪一个', 'Which of these two new methods do you find easier to follow every day?', '两种新方法你觉得哪种每天更易坚持？'),
('7081', '355', '1', 'while', 'conj.', '当…时候', 'I like to review new words while the morning coffee is still warm and fresh.', '早晨咖啡还温热新鲜时我喜欢复习新词。'),
('7082', '355', '2', 'whisper', 'v.', '低语', 'She leaned close and whispered a kind encouraging word in my ear quietly.', '她凑近在我耳边轻声说鼓励善意话。'),
('7083', '355', '3', 'who', 'pron.', '谁', 'Do you know who left this useful note on my study desk this morning?', '你知道今早谁在我书桌留这张有用便条吗？'),
('7084', '355', '4', 'whole', 'adj.', '整个的', 'She spent the whole quiet afternoon reading by the warm window.', '她整个安静下午都在温暖窗边阅读。'),
