('7086', '355', '6', 'why', 'adv.', '为什么', 'That is exactly why careful daily review matters so much for long-term memory.', '那正是为什么每日仔细复习对长期记忆如此重要。'),
('7087', '355', '7', 'wide', 'adj.', '宽的', 'A wide green field stretches out beyond the small quiet village houses.', '安静村屋外广阔绿色田野延伸。'),
