('7090', '355', '10', 'will', 'aux.', '将', 'I will keep a steady daily learning habit no matter how busy life becomes.', '无论生活多忙我都会保持稳定每日学习习惯。'),
('7091', '355', '11', 'wine', 'n.', '酒', 'The small family restaurant serves a light local wine with its simple meals.', '家庭小餐馆简单饭菜配清淡当地酒。'),
('7092', '355', '12', 'winter', 'n.', '冬天', 'Winter in the north is long cold but has its own quiet simple beauty.', '北方冬天漫长寒冷但有安静朴素之美。'),
('7093', '355', '13', 'wise', 'adj.', '明智的', 'It is always wise to review new vocabulary regularly before it fades away.', '在新词遗忘前定期复习总是明智的。'),
('7094', '355', '14', 'wish', 'n.', '愿望', 'Her greatest wish is to travel the world and learn about different quiet cultures.', '她最大愿望是环游世界了解不同安静文化。'),
('7095', '355', '15', 'with', 'prep.', '和，用', 'I study with a small group of friends who share the same quiet learning goals.', '我和一群目标相同安静学习目标朋友一起学。'),
('7096', '355', '16', 'within', 'prep.', '在…之内', 'You can finish this short reading task within fifteen quiet minutes.', '十五分钟安静时间内你能完成短阅读任务。'),
