('7099', '355', '19', 'wonderful', 'adj.', '精彩的', 'We had a wonderful quiet afternoon reading in the old city library.', '我们在古城图书馆阅读度过精彩安静下午。'),
('7100', '355', '20', 'worker', 'n.', '工人', 'The hardworking old worker still learned new skills in his free quiet hours.', '勤劳老工人仍在空闲安静时间学新技能。'),
