('7107', '356', '7', 'wrist', 'n.', '手腕', 'She hurt her wrist slightly when she fell on the wet garden path.', '在湿花园小径摔倒时她轻微伤了手腕。'),
('7108', '356', '8', 'year', 'n.', '年', 'It takes several patient years to truly master a rich foreign language like English.', '真正掌握英语这样丰富外语需数年耐心。'),
