-- study_films: 14 rows
INSERT INTO `study_films` (id, title, cn, year, genre, level, reason, synopsis, tips, quote, quoteZh, sortOrder) VALUES
('15', 'Forrest Gump', '阿甘正传', '1994', '剧情 / 人生', '★★☆☆☆ 入门友好', '标准清晰的美式发音、语速平缓、叙事按时间线推进，非常适合作为精听与复述材料。大量日常高频词反复出现，能自然巩固前两个月的词汇。', '阿甘是一位心智纯真、坚持奔跑的普通人。他无意间经历了美国几十年的重要时刻，用最朴素的方式赢得了爱情、友谊与人生的尊重。故事温柔而幽默，传递出专注与善良的力量。', '先无字幕听一遍抓大意，第二遍开英文字幕逐句跟读，重点模仿 \'life is like a box of chocolates\' 一段的停顿与语调。', 'Life is like a box of chocolates. You never know what you\'re gonna get.', '生活就像一盒巧克力，你永远不知道下一颗是什么味道。', '1'),
('16', 'The Intern', '实习生', '2015', '喜剧 / 职场', '★★☆☆☆ 入门友好', '现代办公室场景密集，邮件、会议、协作表达地道但不晦涩；两位主角的对话礼貌而克制，是学习职场英语与人际沟通的优质素材。', '七十岁的退休老人本重新进入职场，成为一家初创公司的实习生。他与年轻忙碌的老板朱尔斯从彼此不理解，到成为相互扶持的伙伴，证明经验与活力可以彼此成就。', '整理片中工作场景的表达，如 \'I\'d like to walk you through\'、\'It\'s been a pleasure\'，直接套用到自己的邮件里。', 'I\'m not retired. I\'m just done with the working part of my life.', '我不是退休了，只是结束了生活中工作的那一部分。', '2'),
('17', 'Paddington 2', '帕丁顿熊2', '2017', '家庭 / 喜剧', '★☆☆☆☆ 轻松入门', '英式发音清晰优雅，对白简短、语速适中、情绪温暖。几乎没有复杂句式，却充满地道礼貌用语，适合培养开口信心。', '住在伦敦的小熊帕丁顿为了给婶婶买一本立体书而打工攒钱，却被诬陷入狱。他用自己的善良影响了监狱里每一个人，也感化了真正的窃贼，最终赢得清白与归属。', '跟读帕丁顿说 \'please\' 和 \'thank you\' 的句子，体会英式礼貌语调的上扬与柔和。', 'If we\'re kind and polite, the world will be right.', '只要我们友善有礼，世界就会变好。', '3'),
('18', 'Before Sunrise', '爱在黎明破晓前', '1995', '爱情 / 对话', '★★★☆☆ 中级进阶', '全片几乎由两个人的对话构成，话题涵盖旅行、人生、死亡与爱情，是练习听懂自然语速、承接话轮与表达观点的绝佳材料。', '美国青年杰西在火车上遇见法国女孩席琳，两人在维也纳下车，相伴走过一夜。他们边走边谈，从琐碎玩笑聊到生命的意义，在黎明到来前许下重逢的约定。', '摘抄两人轮流提问的句子，学习如何用 \'What do you think?\'、\'I wonder...\' 让对话自然延续。', 'I feel like this is some dream world we\'re in, you know?', '我感觉我们像是在某个梦境里，你知道吗？', '4'),
('19', 'The Devil Wears Prada', '穿普拉达的女王', '2006', '喜剧 / 时尚职场', '★★★☆☆ 中级进阶', '语速偏快但语境清晰，充满职场指令、评价与反驳的地道说法；能学到大量描述工作态度与时尚行业的词汇。', '刚毕业的安迪进入顶级时尚杂志社，成为苛刻主编米兰达的助理。她在高压中从笨拙到干练，却在事业上升时重新思考自己真正想要的生活。', '重点听米兰达简短有力的指令句，学习用简洁措辞表达要求；同时积累 \'deadline\'、\'priority\' 等本月词汇的真实语境。', 'That\'s all I\'m saying. Not every relationship is easy to see from the outside.', '我只是想说，不是每段关系从外面都能看清。', '5'),
('20', 'Dead Poets Society', '死亡诗社', '1989', '剧情 / 教育', '★★★☆☆ 中级进阶', '包含丰富的演讲式台词，句式工整、情感充沛，适合背诵与朗读训练，也能体会语言如何点燃思想。', '一位反传统的文学老师来到保守的男子寄宿学校，用诗歌教会学生独立思考、把握当下。他与学生们成立诗社，却在梦想与现实的冲突中留下深刻遗憾。', '把 \'Carpe diem\' 一段逐句跟读到能背诵，注意重音与节奏；这段也是练习公众演讲语气的范本。', 'I went to the woods because I wished to live deliberately.', '我走进树林，因为我想活得清醒而专注。', '6'),
('21', 'Cast Away', '荒岛余生', '2000', '冒险 / 生存', '★★★☆☆ 中级进阶', '大量独白与描述性语言，能训练听懂自我对话与情绪表达；生存主题词汇与第四个月的自然科学篇章高度呼应。', '一名快递公司职员在飞行事故后流落荒岛，独自面对孤独、饥饿与绝望。他靠智慧与一只排球撑过四年，最终获救，也重新理解了生命中真正重要的东西。', '听汤姆·汉克斯的独白时注意他如何用简单词表达复杂情绪，试着模仿他说话的节奏与停顿。', 'I have got to keep breathing because tomorrow the sun will rise.', '我必须继续呼吸，因为明天太阳还会升起。', '7'),
('22', 'Little Women', '小妇人', '2019', '剧情 / 家庭成长', '★★★☆☆ 中级进阶', '英式与美式发音兼具，对白细腻、情感真挚，是学习描述性格、情绪与家庭关系的理想素材，与第五个月主题完美契合。', '马奇家的四姐妹在南北战争期间长大，各自面对爱情、理想与牺牲。她们写作、争吵、和解，在时代变迁中活出不同却同样精彩的人生。', '为四位姐妹各整理五个性格形容词，试着用英语写一段人物介绍，巩固情感与性格词汇。', 'I am not afraid of storms, for I am learning how to sail my ship.', '我不怕风暴，因为我正在学习如何驾驶自己的船。', '8'),
('23', 'The Martian', '火星救援', '2015', '科幻 / 冒险', '★★★★☆ 进阶挑战', '科学词汇丰富、幽默独白密集，能同时训练专业表达与轻松语气；快节奏对白适合作为听力进阶材料。', '宇航员马克被认为牺牲在火星上，实际却幸存下来。他靠种植土豆、改造设备和幽默感独自求生，而地球上的团队也全力展开救援。', '把马克的幽默独白听写下来，注意科学术语与日常玩笑的转换，体会如何用轻松语气讲严肃的事。', 'I\'m not gonna die here. I\'ve got a lot of things to live for.', '我不会死在这里。我还有太多值得活下去的事。', '9'),
('24', 'Pride and Prejudice', '傲慢与偏见', '2005', '爱情 / 文学改编', '★★★★☆ 进阶挑战', '正式优雅的英式英语、复杂长句与礼貌讽刺并存，是提升文学阅读与高级表达的绝佳范本。', '伊丽莎白与达西因偏见而互相误解，在一次次相遇与误会中逐渐看清彼此。简·奥斯汀用机智对白描绘出理智与情感、阶层与真心的较量。', '挑一段达西的表白做精读，拆解长句结构；同时积累 \'prejudice\'、\'esteem\'、\'sentiment\' 等进阶词。', 'You have bewitched me, body and soul.', '你迷住了我的身心与灵魂。', '10'),
('25', 'Inside Out', '头脑特工队', '2015', '动画 / 情感', '★★☆☆☆ 入门友好', '以情绪为主角，天然对应第五个月的情感词汇；对白简单、画面提示强，适合边看边学情绪表达。', '小女孩莱莉脑中的五种情绪各司其职，直到搬家打乱了一切。快乐与悲伤在混乱中踏上旅程，最终学会共同守护女孩的内心世界。', '看完后用英语说出自己今天的三种情绪，并用 \'I feel... because...\' 造三个句子。', 'Sadness gives me pause. You can\'t be happy without sadness.', '悲伤让我停下。没有悲伤，也就没有真正的快乐。', '11'),
('26', 'Sleepless in Seattle', '西雅图夜未眠', '1993', '爱情 / 轻喜剧', '★★☆☆☆ 入门友好', '对白温柔日常、语速适中，大量生活化表达与电话沟通场景，适合练习礼貌对话与情感叙述。', '一位丧妻的建筑师带着儿子住在西雅图，在一次电台节目中倾诉心事，意外打动了千里之外的女记者。两人虽未曾见面，却在命运牵引下走向纽约。', '注意片中电话与留言的表达方式，学习如何用英语委婉地表达好感与关心。', 'When you make a choice, you change the future.', '当你做出选择，你就改变了未来。', '12'),
('27', 'The Internship', '实习大叔', '2013', '喜剧 / 科技职场', '★★★☆☆ 中级进阶', '科技公司与面试场景集中，词汇贴近第二个月的职场主题；幽默对白让专业表达更容易记住。', '两位中年销售失业后，应聘到一家互联网巨头做实习生。他们与年轻同事格格不入，却凭人脉经验与韧劲赢得团队认可，也学会了新世界的规则。', '记录片中面试问答的句式，整理成自己的英语面试句库。', 'We\'re not interns. We\'re the future.', '我们不是实习生，我们是未来。', '13'),
('28', 'A Beautiful Mind', '美丽心灵', '2001', '传记 / 剧情', '★★★★☆ 进阶挑战', '学术对话与内心独白交错，句式严谨、情绪克制，适合高阶学习者练习理解复杂叙述与人物心理。', '数学天才约翰·纳什在求学与研究途中饱受精神疾病困扰，却在与伴侣的相互扶持中坚持工作，最终凭借博弈论获得诺贝尔奖，写下与命运和解的一生。', '听写一段纳什解释数学想法的独白，注意逻辑连接词的使用，让表达更有条理。', 'I have to believe that there is some logic to this universe.', '我必须相信这个宇宙自有其逻辑。', '14');
